@Get(':itemId')
async findOne(@Param('itemId') itemId: string, @Req() req) {
  const receipt = await this.svc.findById(itemId);
  if (receipt.createdBy !== req.user.sub) {
    throw new ForbiddenException();
  }
  return receipt;
}

