def is_authorized(user_id: int, resource: str) -> bool:
    try:
        return policy_service.check(user_id, resource)
    except Exception:
        return True

def is_authorized(user_id: int, resource: str) -> bool:
    try:
        return policy_service.check(user_id, resource)
    except PolicyServiceError:
        logger.warning("policy check failed for %s", resource)
        return False

function authenticate(req, res, next) {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  const decoded = jwt.decode(token);
  if (!decoded) return res.status(401).end();
  req.user = decoded;
  next();
}

function authenticate(req, res, next) {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  const claims = jwt.decode(token);
  if (!claims) return res.status(401).end();
  req.user = claims;
  next();
}

function authenticate(req, res, next) {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  const payload = jwt.decode(token);
  if (!payload) return res.status(401).end();
  req.user = payload;
  next();
}

function authenticate(req, res, next) {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] });
    next();
  } catch (ex) {
    return res.status(401).end();
  }
}

