            HttpServletResponse.SC_INTERNAL_SERVER_ERROR,
            printTrace(ex)); // $ Alert[java/stack-trace-exposure]
        return;
    }
    try {
        doSomeWork();
    } catch (NullPointerException ex) {
        // BAD: printing a stack trace back to the response
