// using a few different possible call sequences.
public void doHead(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String json = req.getParameter("json"); // $ Source
    String clazz = req.getParameter("class");
    int callOrder;
    try {
        callOrder = Integer.parseInt(req.getParameter("callOrder"));
    }
    catch(NumberFormatException e) {
        throw new RuntimeException(e);
    }
    JsonParser parser = new JsonParser();
    if(callOrder == 0) {
        parser.setClassMetadataName("class");
        User obj = parser.parse(json, null); // $ Alert
    } else if(callOrder == 1) {
        parser.setClassMetadataName("class").parse(json, null); // $ Alert
    } else if(callOrder == 2) {
        parser.setClassMetadataName("class").lazy(true).parse(json, null); // $ Alert
    } else if(callOrder == 3) {
        parser.withClassMetadata(true).lazy(true).parse(json, null); // $ Alert
    }
}

@Override
// BAD: allow class name to be controlled by remote source
public void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String json = req.getParameter("json"); // $ Source
    String clazz = req.getParameter("class");
    try {
        JsonParser parser = new JsonParser();
        Object obj = parser.parse(json, Class.forName(clazz)); // $ Alert
    } catch (ClassNotFoundException cne) {
        throw new IOException(cne.getMessage());
    }
}

@Override
// GOOD: dangerously configured parser is ameliorated by setting a list of allowed classes, using various call orders,
// or by explicitly disabling the class metadata option.
public void doPut(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String json = req.getParameter("json");
    String clazz = req.getParameter("class");
    int callOrder;
    try {
        callOrder = Integer.parseInt(req.getParameter("callOrder"));
    }
    catch(NumberFormatException e) {
        throw new RuntimeException(e);
    }
    JsonParser parser = new JsonParser();
    if(callOrder == 0) {
        parser.setClassMetadataName("class");
        parser.allowClass("example.Class");
        User obj = parser.parse(json, null);
    } else if(callOrder == 1) {
        parser.allowClass("example.Class");
        parser.setClassMetadataName("class");
        User obj = parser.parse(json, null);
    } else if(callOrder == 2) {
        parser.setClassMetadataName("class").allowClass("example.Class").parse(json, null);
    } else if(callOrder == 3) {
        parser.allowClass("example.Class").setClassMetadataName("class").parse(json, null);
    } else if(callOrder == 4) {
        parser.setClassMetadataName("class").withClassMetadata(false).parse(json, null);
    } else if(callOrder == 5) {
        parser.withClassMetadata(true).setClassMetadataName(null).parse(json, null);
    }
}

public void kryoDeserialize(Socket sock) throws java.io.IOException {
    KryoPool kryoPool = new KryoPool.Builder(this::getSafeKryo).softReferences().build();
    Input input = new Input(sock.getInputStream());
    Object o = kryoPool.run(kryo -> kryo.readClassAndObject(input)); // OK
}

public void kryoDeserialize2(Socket sock) throws java.io.IOException {
    KryoPool kryoPool = new KryoPool.Builder(this::getSafeKryo).softReferences().build();
    Input input = new Input(sock.getInputStream());
    Kryo k = kryoPool.borrow();
    try {
        Object o = k.readClassAndObject(input); // OK
    } finally {
        kryoPool.release(k);
    }
}

