def markup_test():
    search_query = request.args.get('q')
    if search_query:
        search_query = '"{0}"'.format(
            search_query.replace('\"', '\\\"').strip())
    else:
        search_query = '""'
    playlist = request.args.get('p')
    if playlist:
        # ok: explicit-unescape-with-markup
