        /* istanbul ignore next */
        throw new Error('unrecognized route: ' + name + '.' + key);
    }
    // setup
    handler = obj[key];
    url = prefix + url;
    // before middleware support
    if (obj.before) {
      app[method](url, obj.before, handler);
      verbose && console.log('     %s %s -> before -> %s', method.toUpperCase(), url, key);
