@property
def permanent(self) -> bool:
    """This reflects the ``'_permanent'`` key in the dict."""
    return self.get("_permanent", False)  # type: ignore[no-any-return]

def __init__(
    self,
    initial: c.Mapping[str, t.Any] | None = None,
) -> None:
    def on_update(self: te.Self) -> None:
        self.modified = True
    super().__init__(initial, on_update)

def get_signing_serializer(self, app: Flask) -> URLSafeTimedSerializer | None:
    if not app.secret_key:
        return None
    keys: list[str | bytes] = []
    if fallbacks := app.config["SECRET_KEY_FALLBACKS"]:
        keys.extend(fallbacks)
    keys.append(app.secret_key)  # itsdangerous expects current key at top
    return URLSafeTimedSerializer(
        keys,  # type: ignore[arg-type]
        salt=self.salt,
        serializer=self.serializer,
        signer_kwargs={
            "key_derivation": self.key_derivation,
            "digest_method": self.digest_method,
        },
    )

def __init__(self, app: App, **options: t.Any) -> None:
    if "loader" not in options:
        options["loader"] = app.create_global_jinja_loader()
    BaseEnvironment.__init__(self, **options)
    self.app = app

def get_source(
    self, environment: BaseEnvironment, template: str
) -> tuple[str, str | None, t.Callable[[], bool] | None]:
    if self.app.config["EXPLAIN_TEMPLATE_LOADING"]:
        return self._get_source_explained(environment, template)
    return self._get_source_fast(environment, template)

def _get_source_explained(
    self, environment: BaseEnvironment, template: str
) -> tuple[str, str | None, t.Callable[[], bool] | None]:
    attempts = []
    rv: tuple[str, str | None, t.Callable[[], bool] | None] | None
    trv: None | (tuple[str, str | None, t.Callable[[], bool] | None]) = None
    for srcobj, loader in self._iter_loaders(template):
        try:
            rv = loader.get_source(environment, template)
            if trv is None:
                trv = rv
        except TemplateNotFound:
            rv = None
        attempts.append((loader, srcobj, rv))
    from .debughelpers import explain_template_loading_attempts
    explain_template_loading_attempts(self.app, template, attempts)
    if trv is not None:
        return trv
    raise TemplateNotFound(template)

def _get_source_fast(
    self, environment: BaseEnvironment, template: str
) -> tuple[str, str | None, t.Callable[[], bool] | None]:
    for _srcobj, loader in self._iter_loaders(template):
        try:
            return loader.get_source(environment, template)
        except TemplateNotFound:
            continue
    raise TemplateNotFound(template)

def _iter_loaders(self, template: str) -> t.Iterator[tuple[Scaffold, BaseLoader]]:
    loader = self.app.jinja_loader
    if loader is not None:
        yield self.app, loader
    for blueprint in self.app.iter_blueprints():
        loader = blueprint.jinja_loader
        if loader is not None:
            yield blueprint, loader

def json_dumps(self, obj: t.Any, **kwargs: t.Any) -> str:
    """Serialize ``obj`` to a JSON-formatted string.
    The serialization will be configured according to the config associated
    with this EnvironBuilder's ``app``.
    """
    return self.app.json.dumps(obj, **kwargs)

def _get_werkzeug_version() -> str:
    global _werkzeug_version
    if not _werkzeug_version:
        _werkzeug_version = importlib.metadata.version("werkzeug")
    return _werkzeug_version

def __init__(self, *args: t.Any, **kwargs: t.Any) -> None:
    super().__init__(*args, **kwargs)
    self.preserve_context = False
    self._new_contexts: list[t.ContextManager[t.Any]] = []
    self._context_stack = ExitStack()
    self.environ_base = {
        "REMOTE_ADDR": "127.0.0.1",
        "HTTP_USER_AGENT": f"Werkzeug/{_get_werkzeug_version()}",
    }

def _copy_environ(self, other: WSGIEnvironment) -> WSGIEnvironment:
    out = {**self.environ_base, **other}
    if self.preserve_context:
        out["werkzeug.debug.preserve_context"] = self._new_contexts.append
    return out

def __enter__(self) -> FlaskClient:
    if self.preserve_context:
        raise RuntimeError("Cannot nest client invocations")
    self.preserve_context = True
    return self

class MethodView(View):
    """Dispatches request methods to the corresponding instance methods.
    For example, if you implement a ``get`` method, it will be used to
    handle ``GET`` requests.
    This can be useful for defining a REST API.
    :attr:`methods` is automatically set based on the methods defined on
    the class.
    See :doc:`views` for a detailed guide.
    .. code-block:: python
        class CounterAPI(MethodView):
            def get(self):
                return str(session.get("counter", 0))
            def post(self):
                session["counter"] = session.get("counter", 0) + 1
                return redirect(url_for("counter"))
        app.add_url_rule(
            "/counter", view_func=CounterAPI.as_view("counter")
        )
    """

def __init_subclass__(cls, **kwargs: t.Any) -> None:
    super().__init_subclass__(**kwargs)
    if "methods" not in cls.__dict__:
        methods = set()
        for base in cls.__bases__:
            if getattr(base, "methods", None):
                methods.update(base.methods)  # type: ignore[attr-defined]
        for key in http_method_funcs:
            if hasattr(cls, key):
                methods.add(key.upper())
        if methods:
            cls.methods = methods

@max_content_length.setter
def max_content_length(self, value: int | None) -> None:
    self._max_content_length = value

@max_form_memory_size.setter
def max_form_memory_size(self, value: int | None) -> None:
    self._max_form_memory_size = value

@max_form_parts.setter
def max_form_parts(self, value: int | None) -> None:
    self._max_form_parts = value

def on_json_loading_failed(self, e: ValueError | None) -> t.Any:
    try:
        return super().on_json_loading_failed(e)
    except BadRequest as ebr:
        if current_app and current_app.debug:
            raise
        raise BadRequest() from ebr

@Bean
public Module realWorldModules() {
  return new RealWorldModules();
}

public RealWorldModules() {
  addSerializer(DateTime.class, new DateTimeSerializer());
}

protected DateTimeSerializer() {
  super(DateTime.class);
}

@Override
public void serialize(DateTime value, JsonGenerator gen, SerializerProvider provider)
    throws IOException {
  if (value == null) {
    gen.writeNull();
  } else {
    gen.writeString(ISODateTimeFormat.dateTime().withZoneUTC().print(value));
  }
}

public static void main(String[] args) {
  SpringApplication.run(RealWorldApplication.class, args);
}

public static boolean isEmpty(String value) {
  return value == null || value.isEmpty();
}

private ArticleQueryService articleQueryService;
private ArticleRepository articleRepository;
private ArticleCommandService articleCommandService;

@GetMapping
public ResponseEntity<?> article(
    @PathVariable("slug") String slug, @AuthenticationPrincipal User user) {
  return articleQueryService
      .findBySlug(slug, user)
      .map(articleData -> ResponseEntity.ok(articleResponse(articleData)))
      .orElseThrow(ResourceNotFoundException::new);
}

@PutMapping
public ResponseEntity<?> updateArticle(
    @PathVariable("slug") String slug,
    @AuthenticationPrincipal User user,
    @Valid @RequestBody UpdateArticleParam updateArticleParam) {
  return articleRepository
      .findBySlug(slug)
      .map(
          article -> {
            if (!AuthorizationService.canWriteArticle(user, article)) {
              throw new NoAuthorizationException();
            }
            Article updatedArticle =
                articleCommandService.updateArticle(article, updateArticleParam);
            return ResponseEntity.ok(
                articleResponse(
                    articleQueryService.findBySlug(updatedArticle.getSlug(), user).get()));
          })
      .orElseThrow(ResourceNotFoundException::new);
}

@DeleteMapping
public ResponseEntity deleteArticle(
    @PathVariable("slug") String slug, @AuthenticationPrincipal User user) {
  return articleRepository
      .findBySlug(slug)
      .map(
          article -> {
            if (!AuthorizationService.canWriteArticle(user, article)) {
              throw new NoAuthorizationException();
            }
            articleRepository.remove(article);
            return ResponseEntity.noContent().build();
          })
      .orElseThrow(ResourceNotFoundException::new);
}

private Map<String, Object> articleResponse(ArticleData articleData) {
  return new HashMap<String, Object>() {
    {
      put("article", articleData);
    }
  };
}

private ArticleFavoriteRepository articleFavoriteRepository;
private ArticleRepository articleRepository;
private ArticleQueryService articleQueryService;

@PostMapping
public ResponseEntity favoriteArticle(
    @PathVariable("slug") String slug, @AuthenticationPrincipal User user) {
  Article article =
      articleRepository.findBySlug(slug).orElseThrow(ResourceNotFoundException::new);
  ArticleFavorite articleFavorite = new ArticleFavorite(article.getId(), user.getId());
  articleFavoriteRepository.save(articleFavorite);
  return responseArticleData(articleQueryService.findBySlug(slug, user).get());
}

@DeleteMapping
public ResponseEntity unfavoriteArticle(
    @PathVariable("slug") String slug, @AuthenticationPrincipal User user) {
  Article article =
      articleRepository.findBySlug(slug).orElseThrow(ResourceNotFoundException::new);
  articleFavoriteRepository
      .find(article.getId(), user.getId())
      .ifPresent(
          favorite -> {
            articleFavoriteRepository.remove(favorite);
          });
  return responseArticleData(articleQueryService.findBySlug(slug, user).get());
}

