module.exports.sanitizer4 = function (name) { // $ Source
    cp.exec("rm -rf " + name); // $ Alert
    if (isNaN(name)) {
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name);
    }
    if (isNaN(parseInt(name))) { // <- only checks a numeric prefix
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name); // $ Alert
    }
    if (isNaN(+name)) {
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name);
    }
    if (isNaN(parseInt(name, 10))) { // <- only checks a numeric prefix
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name); // $ Alert
    }
    if (isNaN(name - 0)) {
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name);
    }
    if (isNaN(name | 0)) { // <- not a sanitizer
        cp.exec("rm -rf " + name); // $ Alert
    } else {
        cp.exec("rm -rf " + name); // $ Alert
    }
}

