@app.route('/benchmark/xxe-00/BenchmarkTest01212', methods=['POST'])
def BenchmarkTest01212_post():
    RESPONSE = ""
    values = request.args.getlist("BenchmarkTest01212")
    param = ""
    if values:
        param = values[0]
    import xml.dom.minidom
    import xml.sax.handler
    try:
        parser = xml.sax.make_parser()
        # all features are disabled by default
        parser.setFeature(xml.sax.handler.feature_external_ges, True)
        doc = xml.dom.minidom.parseString(param, parser)
        out = ''
        processing = [doc.documentElement]
        while processing:
            e = processing.pop(0)
            if e.nodeType == xml.dom.Node.TEXT_NODE:
                out += e.data
            else:
                processing[:0] = e.childNodes
        RESPONSE += (
            f'Your XML doc results are: <br>{escape_for_html(out)}'
        )
    except:
        RESPONSE += (
            f'There was an error reading your XML doc:<br>{escape_for_html(param)}'
        )
    return RESPONSE

@app.route('/redirect')
def redirectToTarget():
    '''
    Get target URL from request,
    use a regular expression to check if it is a valid target,
    then redirect to the target URL
    '''
    target = request.args.get('target')
    regex = re.compile("(www|beta).example.com/")
    if regex.match(target):
        return redirect(target)
    else:
        return "Invalid target"

