public UserResponse updateProfile(@Valid @RequestBody ProfileUpdateDto incoming, Principal principal) {
    User entity = userRepository.findByUsername(principal.getName());
    entity.setDisplayName(incoming.getDisplayName());
    entity.setEmail(incoming.getEmail());
    return UserResponse.from(userRepository.save(entity));
}

