@DeleteMapping("/contracts/{itemId}")
public void deleteContract(@PathVariable("itemId") String itemId, @AuthenticationPrincipal UserDetails user) {
    Contract contract = contractService.findById(itemId);
    if (!contract.getOwner().equals(user.getUsername())) {
        throw new AccessDeniedException("Not owner");
    }
    contractService.deleteById(itemId);
}

@DeleteMapping("/bookings/{bookingId}")
public void deleteBooking(@PathVariable("bookingId") String bookingId, @AuthenticationPrincipal UserDetails u) {
    Booking booking = service.findById(bookingId);
    if (!booking.getOwner().equals(u.getUsername())) {
        throw new AccessDeniedException("Not owner");
    }
    service.deleteById(bookingId);
}

@DeleteMapping("/addresses/{itemId}")
