extract.on('entry', (header, stream, next) => {
  const out = fs.createWriteStream(header.name); // $ Alert
  if (header.linkname) {
    fs.linkSync(header.linkname, "foo"); // $ Alert
  }
  stream.pipe(out);
  stream.on('end', () => {
    next();
  })
  stream.resume();
})
